Future<void>_openTrailer(String url)async{final ok=await launchUrl(Uri.parse(url),mode:LaunchMode.externalApplication);if(!ok&&mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Treylerni ochib bo‘lmadi.')));}
Future<void>toggle(String id)async{setState(()=>busy=true);try{await ref.read(contentRepositoryProvider).favoriteMovie(id,!favorite);setState(()=>favorite=!favorite);ref.invalidate(favoritesProvider);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(favorite?'Sevimlilarga qo‘shildi':'Sevimlilardan olindi')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(friendlyError(e))));}finally{if(mounted)setState(()=>busy=false);}}}
